import { parsePrativedanAssessmentJson } from '../services/bff/src/services/prativedan-assessment-json.js';
/** Consume only the synthetic fixture generated by the owned CI database.
 * Actual source/request/claim interoperability and pure rendering are proved
 * separately from runtime completion, settlement and publication authority.
 */
import { lstatSync, readFileSync, realpathSync, writeFileSync } from 'node:fs';
import { resolve, join } from 'node:path';
import { z } from 'zod';
import { canonicalJson } from '../packages/ledger/src/canonicalise.js';
import {
  prativedanAssessmentClaimSchema,
  prativedanAssessmentRequestedSchema,
  PRATIVEDAN_RENDERER_CONFIG_VERSION,
  PRATIVEDAN_RENDERER_CONFIG_TEXT,
  PRATIVEDAN_RENDERER_CONFIG_SHA256,
} from '../packages/types/src/index.js';
import { preparePrativedanAssessmentDraftSource } from '../services/bff/src/services/prativedan-assessment-draft-source.js';
import { verifyPrativedanAssessmentRendering } from '../services/bff/src/services/prativedan-assessment-draft-output.js';
import { prativedanTextHash } from '../services/bff/src/services/prativedan-draft-source.js';

const rendererSchema = z
  .object({
    schema_version: z.literal(1),
    evidence_kind: z.literal('pure_renderer_from_disposable_pg_source'),
    prepared_readback: z.unknown(),
    expected_binding: z.unknown(),
    normalized_input_text: z.string(),
    runtime_normalized_input_sha256: z.string(),
    renderer_config_version: z.literal(PRATIVEDAN_RENDERER_CONFIG_VERSION),
    renderer_config_text: z.literal(PRATIVEDAN_RENDERER_CONFIG_TEXT),
    renderer_config_sha256: z.literal(PRATIVEDAN_RENDERER_CONFIG_SHA256),
    runtime_output_text: z.string(),
    runtime_output_sha256: z.string(),
    output: z.unknown(),
    python_output_representation_text: z.string(),
    python_output_representation_sha256: z.string(),
    runtime_receipts_proven: z.literal(false),
    settlement_proven: z.literal(false),
    publication_allowed: z.literal(false),
  })
  .strict();

function check(condition: boolean): void {
  if (!condition) throw new Error('Synthetic interoperability refused');
}
function read(directory: string, name: string): unknown {
  const path = join(directory, name);
  const info = lstatSync(path);
  check(
    info.uid === process.getuid?.() &&
      info.isFile() &&
      !info.isSymbolicLink() &&
      info.size <= 8388608 &&
      (info.mode & 0o777) === 0o600,
  );
  return parsePrativedanAssessmentJson(readFileSync(path, 'utf8'));
}

try {
  check(process.argv.length === 3);
  const directory = resolve(process.argv[2]!);
  const info = lstatSync(directory);
  check(
    info.uid === process.getuid?.() &&
      info.isDirectory() &&
      !info.isSymbolicLink() &&
      realpathSync(directory) === directory &&
      (info.mode & 0o777) === 0o700,
  );
  for (const phase of ['initial', 'final']) {
    const path = join(directory, phase);
    const state = lstatSync(path);
    check(
      state.isDirectory() &&
        !state.isSymbolicLink() &&
        state.uid === process.getuid?.() &&
        (state.mode & 0o777) === 0o700 &&
        realpathSync(path) === path,
    );
  }
  const fixture = z
    .object({
      schema_version: z.literal(1),
      fixture_kind: z.literal('disposable_postgres_assessment_v2'),
      requested_readback: prativedanAssessmentRequestedSchema,
      sql_input_projection: z.unknown(),
      expected_binding: z.unknown(),
      claim_first: prativedanAssessmentClaimSchema,
      claim_replay: prativedanAssessmentClaimSchema,
      actual_ledger_rows: z.array(z.unknown()).min(1).max(20),
    })
    .strict()
    .parse(read(directory, 'pg-fixture.json'));
  check(fixture.claim_first.claimed && !fixture.claim_replay.claimed);
  check(
    canonicalJson(fixture.claim_first.readback) === canonicalJson(fixture.claim_replay.readback),
  );
  const results = [];
  for (const phase of ['initial', 'final']) {
    const renderer = rendererSchema.parse(read(directory, `${phase}/renderer.json`));
    const journal = phase === 'initial' ? fixture.requested_readback : fixture.claim_first.readback;
    check(canonicalJson(renderer.prepared_readback) === canonicalJson(journal));
    check(canonicalJson(renderer.expected_binding) === canonicalJson(fixture.expected_binding));
    const prepared = preparePrativedanAssessmentDraftSource(journal, journal.request_text);
    check(canonicalJson(prepared.rendererInput) === canonicalJson(fixture.sql_input_projection));
    check(
      canonicalJson(prepared.rendererInput) ===
        canonicalJson(parsePrativedanAssessmentJson(renderer.normalized_input_text)),
    );
    check(
      prativedanTextHash(renderer.normalized_input_text) ===
        renderer.runtime_normalized_input_sha256,
    );
    check(prativedanTextHash(renderer.runtime_output_text) === renderer.runtime_output_sha256);
    check(
      prativedanTextHash(renderer.python_output_representation_text) ===
        renderer.python_output_representation_sha256,
    );
    check(
      canonicalJson(parsePrativedanAssessmentJson(renderer.runtime_output_text)) ===
        canonicalJson(renderer.output),
    );
    check(
      canonicalJson(parsePrativedanAssessmentJson(renderer.python_output_representation_text)) ===
        canonicalJson(renderer.output),
    );
    if (journal.state !== 'requested') {
      check(journal.normalized_input_text === renderer.normalized_input_text);
      check(journal.runtime_normalized_input_sha256 === renderer.runtime_normalized_input_sha256);
    }
    const output = verifyPrativedanAssessmentRendering(prepared, renderer.output);
    const responseOutputText = canonicalJson(output);
    const responseOutputSha256 = prativedanTextHash(responseOutputText);
    // Compute the fifth domain from actual TS serialization; Python's separate
    // representation is never mislabeled as a retained BFF settlement receipt.
    writeFileSync(join(directory, phase, 'ts-response-output.json'), responseOutputText, {
      flag: 'wx',
      mode: 0o600,
    });
    results.push({
      phase,
      sourceSha256: journal.source_sha256,
      requestSha256: journal.request_sha256,
      runtimeNormalizedInputSha256: renderer.runtime_normalized_input_sha256,
      runtimeOutputSha256: renderer.runtime_output_sha256,
      responseOutputSha256,
      rendererConfigSha256: PRATIVEDAN_RENDERER_CONFIG_SHA256,
    });
  }
  writeFileSync(
    join(directory, 'ts-verification.json'),
    JSON.stringify({
      schemaVersion: 1,
      results,
      sourceRequestClaimInteroperability: true,
      pureRenderingVerified: true,
      runtimeReceiptsProven: false,
      settlementProven: false,
      publicationAllowed: false,
    }),
    { flag: 'wx', mode: 0o600 },
  );
  console.log(
    'Dedicated assessment PostgreSQL/Python/TypeScript source, claim and pure-renderer interoperability passed; runtime receipts and settlement remain unproven.',
  );
} catch {
  console.error('Dedicated assessment synthetic interoperability refused.');
  process.exitCode = 1;
}
